-- Corrected US recount from the working table: granted utility patents filed since 1 Nov 1996, by origin and top owner names.
-- This is the exact text I ran. It processed 14.46 MB.
WITH us AS (SELECT DISTINCT publication_number, o AS owner FROM nokia_analytics.portfolio_30y, UNNEST(owners) AS o WHERE country_code = 'US' AND grant_date > 0 AND SUBSTR(kind_code, 1, 1) IN ('A', 'B', 'E')), c AS (SELECT publication_number, owner, CASE WHEN REGEXP_CONTAINS(UPPER(owner), r'TCL|VACUUM|OPTRONICS|KABEL|CABLE|FIBRES|ESPACE|TELSPACE|MOBILE COMM|RADIOTELEPHONE|SUBMARCOM|SUBMARINE|TRANSP SOLUTION|ALSTHOM|ALSTHOLM|ALTHOM|ALTSHOM|COMMISSARIAT|INRIA|LUCENT KK|^TRT ') THEN 'Needs review' WHEN UPPER(owner) LIKE '%INFINERA%' THEN 'Infinera' WHEN REGEXP_CONTAINS(UPPER(owner), r'SHANGH[AI]{2} BELL') THEN 'Shanghai Bell' WHEN REGEXP_CONTAINS(UPPER(owner), r'S[IE]{2}M[EA]NS') THEN 'Nokia Siemens Networks' WHEN REGEXP_CONTAINS(UPPER(owner), r'^LUCENT|ATT CORP LUCENT') THEN 'Lucent' WHEN REGEXP_CONTAINS(UPPER(owner), r'ALCATEL|LUCENT') THEN 'Alcatel and Alcatel-Lucent' WHEN UPPER(owner) LIKE '%NOKIA%' THEN 'Nokia' ELSE 'Other' END AS origin FROM us) SELECT 'origin' AS row_type, origin AS label, COUNT(DISTINCT publication_number) AS patents, COUNT(DISTINCT owner) AS names FROM c GROUP BY origin UNION ALL SELECT 'total', 'Unique patents', COUNT(DISTINCT publication_number), COUNT(DISTINCT owner) FROM c UNION ALL SELECT 'total', 'Listings', COUNT(*), COUNT(DISTINCT owner) FROM c UNION ALL (SELECT 'name', owner, COUNT(DISTINCT publication_number), 1 FROM c GROUP BY owner ORDER BY 3 DESC LIMIT 15) ORDER BY row_type, patents DESC;
